// === Tab: mySketch ===
// MIPMAPってこんな違うの？？
// mipmapはMIN_FILTERの精度を高めるための物なので、
// MAGの方はLINEARとNEARESTだけですね

function setup() {
  createCanvas(window.innerWidth, window.innerWidth*.75, WEBGL);
  createCubemapShader();

  const gl = this._renderer.GL;
  const cubemapSources = getCubemapSources();

  registCubemap(gl, 3, cubemapSources);
  registCubemap(gl, 4, cubemapSources, true);

  // 一応0に戻しておく
  gl.activeTexture(gl.TEXTURE0);
}

function registCubemap(gl, index, srcArray, mipmap = false){
  const tex = gl.createTexture();
  // 3番に入れる
  gl.activeTexture(gl.TEXTURE0 + index);
  gl.bindTexture(gl.TEXTURE_CUBE_MAP, tex);

  const cubeTargets = [
    gl.TEXTURE_CUBE_MAP_POSITIVE_X, gl.TEXTURE_CUBE_MAP_NEGATIVE_X,
    gl.TEXTURE_CUBE_MAP_POSITIVE_Y, gl.TEXTURE_CUBE_MAP_NEGATIVE_Y,
    gl.TEXTURE_CUBE_MAP_POSITIVE_Z, gl.TEXTURE_CUBE_MAP_NEGATIVE_Z
  ];

  for(let i=0; i<6; i++){
    const src = srcArray[i];
    gl.texImage2D(
      cubeTargets[i], 0, gl.RGBA, src.width, src.height, 0,
      gl.RGBA, gl.UNSIGNED_BYTE, src
    );
  }

  if (mipmap) {
    gl.generateMipmap(gl.TEXTURE_CUBE_MAP);
    gl.texParameteri(gl.TEXTURE_CUBE_MAP, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_CUBE_MAP, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
  }else{
    gl.texParameteri(gl.TEXTURE_CUBE_MAP, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_CUBE_MAP, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  }
}

function draw() {
  orbitControl();
  background(0);
	rotateY(PI/2)
	rotateY(-frameCount * .02);
	rotateX(-frameCount * .01);
  noStroke(); // これが無いとstrokeのshaderで上書きされてしまう

  shader(myShader);
  var gl = this._renderer.GL;
  const pg = myShader._glProgram;
  gl.useProgram(pg);
  const loc = gl.getUniformLocation(pg, "uCubemap");

  gl.uniform1i(loc, 3);
  myShader.setUniform("uTintColor", [0.0, 1.0, 1.0]); // mipmap無し：ブルー
  translate(200, 0, 0);
  box(200);

  gl.uniform1i(loc, 4);
  myShader.setUniform("uTintColor", [0.0, 1.0, 0.0]); // mipmapあり：オレンジ
  translate(-400, 0, 0);
  box(200);
}

function createCubemapShader(){
  const sh = baseMaterialShader();

  myShader = sh.modify({
    vertexDeclarations: `OUT vec3 vLocalPosition;`,
    fragmentDeclarations: `
      IN vec3 vLocalPosition;
      uniform samplerCube uCubemap; 
      uniform vec3 uTintColor;
    `,
  'void afterVertex':`(){vLocalPosition = aPosition;}`,
  'vec4 getFinalColor':`(vec4 color){
      vec4 col = texture(uCubemap, -vLocalPosition);
      col.rgb *= uTintColor;
      return col;
    }`
  });
}

function getCubemapSources(){
  const grs = [];
  const texts = ["R","Y","E","S","T","B"];
  for(let i=0; i<6; i++){
    const gr = createGraphics(512, 512);
    gr.textAlign(CENTER,CENTER).textStyle(ITALIC).textSize(480);
    gr.background(255);
    gr.fill(0);gr.noStroke();
    gr.text(texts[i],256,256);
    grs.push(gr.elt);
  }
  return grs;
}

